export default {"id":"m4l-level-18","number":18,"title":"Bonus references","skillBand":"Textbook","duration":"From the course textbook","summary":"1.1","modules":[{"id":"m4l-m-1-1-1-2","code":"1.1","title":"1.1","blurb":"1.1","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"m4l-b-1-1-1","title":"1.1.1: Comprehensive LOM Class Catalog Reference","blocks":[{"type":"step","title":"1. Overview and Scope","blocks":[{"type":"list","items":["<strong>Lesson ID:</strong> Bonus 1.1.1","<strong>Module / Section:</strong> Bonus 1 / Bonus 1.1","<strong>Track:</strong> <code>m4l-devices</code>","<strong>Target Environment:</strong> Ableton Live 12 Standard / Suite; bundled Cycling '74 Max 9 runtime.","<strong>Primary Source:</strong> Cycling '74: <em>Max 9 Live Object Model (LOM) Reference Manual</em> (Live 12 class specifications).","<strong>Purpose:</strong> Centralized, deep-level technical reference cataloging core and specialized Live Object Model (LOM) classes, properties, callable methods, and observers for Live API utility developers."],"ordered":false},{"type":"prose","html":"<em>Honesty Note:</em> The presence of a device-specific class in this catalog indicates its programmatic availability within the Live Object Model API. It does not imply that a specific tier of Ableton Live (e.g., Intro vs. Standard vs. Suite) includes that instrument/device for sound design coursework."}]},{"type":"step","title":"2. Core Session and Track Classes","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-----------------------------------------------------------------------------------+\n|                              SONG &amp; APPLICATION CLASSES                           |\n+-------------------+-----------------------------------+---------------------------+\n| LOM Class         | Properties (Get / Set)            | Callable Functions (Methods)|\n+-------------------+-----------------------------------+---------------------------+\n| **Song**          | `tempo`, `signature_numerator`,   | `create_audio_track`,     |\n| (`path live_set`) | `signature_denominator`, `is_playing`,| `create_midi_track`,  |\n|                   | `current_song_time`, `scenes`,    | `create_return_track`,    |\n|                   | `tracks`, `return_tracks`,        | `delete_track`,           |\n|                   | `master_track`, `visible_tracks`, | `duplicate_track`,        |\n|                   | `cue_points`, `loop`, `loop_start`| `undo`, `redo`, `jump_to_prev_cue`|\n+-------------------+-----------------------------------+---------------------------+\n| **Track**         | `name`, `color`, `color_index`,   | `delete_device`,          |\n| (`tracks &lt;n&gt;`)    | `mute`, `solo`, `arm`,            | `duplicate_clip_slot`,    |\n|                   | `current_monitoring_state`,       | `jump_in_running_session_clip`,|\n|                   | `can_be_armed`, `has_audio_input`,| `stop_all_clips`          |\n|                   | `has_midi_input`, `clip_slots`,   |                           |\n|                   | `devices`, `mixer_device`         |                           |\n+-------------------+-----------------------------------+---------------------------+\n| **MixerDevice**   | `volume`, `panning`, `sends`,     | None                      |\n| (`mixer_device`)  | `crossfader_assign`, `song`       |                           |\n+-------------------+-----------------------------------+---------------------------+</pre>"}]},{"type":"step","title":"3. Clip and ClipSlot Classes","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-----------------------------------------------------------------------------------+\n|                              CLIP &amp; CLIPSLOT CLASSES                              |\n+-------------------+-----------------------------------+---------------------------+\n| LOM Class         | Properties (Get / Set)            | Callable Functions (Methods)|\n+-------------------+-----------------------------------+---------------------------+\n| **ClipSlot**      | `has_clip`, `is_playing`,         | `fire`, `stop`,           |\n| (`clip_slots &lt;n&gt;`)| `is_recording`, `is_triggered`,   | `create_clip`,            |\n|                   | `clip`, `canonical_parent`        | `delete_clip`,            |\n|                   |                                   | `duplicate_clip_to`       |\n+-------------------+-----------------------------------+---------------------------+\n| **Clip**          | `name`, `color`, `length`,        | `fire`, `stop`,           |\n| (`clip`)          | `start_time`, `end_time`,         | `get_notes_by_id`,        |\n|                   | `signature_numerator`,            | `get_selected_notes_extended`,|\n|                   | `signature_denominator`,          | `add_new_notes`,          |\n|                   | `is_midi_clip`, `is_audio_clip`,  | `remove_notes_by_id`,     |\n|                   | `warping`, `gain`, `pitch_fine`   | `replace_selected_notes`  |\n+-------------------+-----------------------------------+---------------------------+</pre>"}]},{"type":"step","title":"4. Device and Parameter Classes","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-----------------------------------------------------------------------------------+\n|                              DEVICE &amp; PARAMETER CLASSES                           |\n+-------------------+-----------------------------------+---------------------------+\n| LOM Class         | Properties (Get / Set)            | Callable Functions (Methods)|\n+-------------------+-----------------------------------+---------------------------+\n| **Device**        | `name`, `class_name`, `type`,     | None                      |\n| (`devices &lt;n&gt;`)   | `is_active`, `can_have_chains`,   |                           |\n|                   | `can_have_drum_pads`, `parameters`|                           |\n+-------------------+-----------------------------------+---------------------------+\n| **DeviceParameter**| `name`, `original_name`, `value`,| `str_for_value`,          |\n| (`parameters &lt;n&gt;`)| `min`, `max`, `default_value`,    | `value_for_str`           |\n|                   | `is_quantized`, `is_enabled`,     |                           |\n|                   | `automation_state`                |                           |\n+-------------------+-----------------------------------+---------------------------+\n| **RackDevice**    | `can_show_chains`, `chains`,      | None                      |\n| (`RackDevice`)    | `drum_pads`, `return_chains`,     |                           |\n|                   | `visible_drum_pads`, `macros`     |                           |\n+-------------------+-----------------------------------+---------------------------+\n| **SimplerDevice** | `sample`, `playback_mode`,        | `crop`, `reverse`         |\n|                   | `slicing_playback_mode`           |                           |\n+-------------------+-----------------------------------+---------------------------+\n| **DriftDevice**   | Extends Device; exposes drift     | None                      |\n|                   | specific synthesis parameters     |                           |\n+-------------------+-----------------------------------+---------------------------+\n| **Eq8Device**     | Extends Device; exposes band mode,| None                      |\n|                   | frequency, gain, Q parameters     |                           |\n+-------------------+-----------------------------------+---------------------------+</pre>"}]},{"type":"step","title":"5. Control Surface and Hardware API","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-----------------------------------------------------------------------------------+\n|                         CONTROL SURFACE SCRIPT CLASSES                            |\n+-------------------+-----------------------------------+---------------------------+\n| LOM Class         | Properties (Get / Set)            | Callable Functions (Methods)|\n+-------------------+-----------------------------------+---------------------------+\n| **ControlSurface**| `components`, `controls`,         | `grab_control`,           |\n| (`control_surfaces`| `attached_to_device`             | `release_control`         |\n|  `&lt;index&gt;`)       |                                   |                           |\n+-------------------+-----------------------------------+---------------------------+</pre>"},{"type":"prose","html":"<em>Developer Tip:</em> Use <code>[live.path path control_surfaces 0]</code> to intercept hardware button matrices and rotary encoders on connected Push or Launchkey controllers."}]},{"type":"step","title":"6. Source Citations","blocks":[{"type":"list","items":["Cycling '74. (2024). <em>Max 9 Live Object Model Specification: Complete Class Catalog</em>. San Francisco: Cycling '74.","Ableton AG. (2024). <em>Controlling Live using Max for Live: Reference Index</em>. Ableton Technical Support Knowledge Base."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"m4l-m-2-1-2","code":"2.1","title":"2.1","blurb":"2.1","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"m4l-b-2-1-1","title":"2.1.1: Developer Tooling — maxdiff, git, and CPU Reporter","blocks":[{"type":"step","title":"1. Overview and Scope","blocks":[{"type":"list","items":["<strong>Lesson ID:</strong> Bonus 2.1.1","<strong>Module / Section:</strong> Bonus 2 / Bonus 2.1","<strong>Track:</strong> <code>m4l-devices</code>","<strong>Target Environment:</strong> Ableton Live 12 Standard / Suite; bundled Cycling '74 Max 9 runtime; git version control.","<strong>Primary Source:</strong> Ableton: <code>maxdevtools</code> repository (<code>B:\\Documents\\User Manuals\\Ableton\\Max for Live\\maxdevtools-main\\</code>).","<strong>Purpose:</strong> Provide an advanced developer survey of official open-source tooling built by Ableton for version control, text diffing, and performance profiling of Max for Live devices."],"ordered":false}]},{"type":"step","title":"2. The maxdevtools Repository Overview","blocks":[{"type":"prose","html":"The <code>maxdevtools</code> suite is an official open-source toolchain maintained by Ableton engineers for professional Max for Live development:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">maxdevtools/\n├── maxdiff/                 &lt;-- CLI tool converting binary .amxd / .maxpat to readable JSON diffs\n├── cpu-reporter/            &lt;-- Specialized M4L device measuring real-time device CPU load in Live\n├── m4l-production-guidelines/ &lt;-- Complete engineering specification markdown files\n└── patch-code-standard/     &lt;-- Visual layout rules and audit criteria</pre>"}]},{"type":"step","title":"3. Version Control and maxdiff","blocks":[{"type":"heading","text":"3.1 The Binary .amxd Version Control Challenge","level":3},{"type":"prose","html":"Standard git version control treats <code>.amxd</code> files as opaque binary blobs. When a developer pushes a change:"},{"type":"list","items":["<code>git diff</code> outputs: <code>Binary files a/MyDevice.amxd and b/MyDevice.amxd differ</code>.","Developers cannot review individual object additions, coordinate tweaks, or script modifications in pull requests."],"ordered":false},{"type":"heading","text":"3.2 The maxdiff Solution","level":3},{"type":"prose","html":"<code>maxdiff</code> is a Python CLI utility that parses <code>.amxd</code> and <code>.maxpat</code> JSON containers, normalizes arbitrary dictionary keys, strips non-functional layout noise, and outputs human-readable text diffs:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                             GIT DIFF WITH MAXDIFF                             |\n+-------------------------------------------------------------------------------+\n|                                                                               |\n|  $ git diff MyDevice.amxd                                                     |\n|                                                                               |\n|  --- a/MyDevice.amxd (patcher structure)                                      |\n|  +++ b/MyDevice.amxd (patcher structure)                                      |\n|  @@ -42,7 +42,7 @@                                                           |\n|   {                                                                           |\n|     \"box\": {                                                                  |\n|  -    \"maxclass\": \"newobj\", \"text\": \"svf~ 1000. 0.5\"                         |\n|  +    \"maxclass\": \"newobj\", \"text\": \"svf~ 1200. 0.707\"                       |\n|     }                                                                         |\n|   }                                                                           |\n|                                                                               |\n+-------------------------------------------------------------------------------+</pre>"},{"type":"heading","text":"3.3 Configuring git to Use maxdiff","level":3},{"type":"prose","html":"In your project repository:"},{"type":"list","items":["Add to <code>.gitattributes</code>: ``` *.amxd diff=maxdiff *.maxpat diff=maxdiff ```","Configure <code>.git/config</code>: ```ini [diff \"maxdiff\"] textconv = python -m maxdiff ```"],"ordered":true}]},{"type":"step","title":"4. Performance Profiling with cpu-reporter","blocks":[{"type":"prose","html":"The <code>cpu-reporter</code> is a specialized diagnostic Max for Live device provided in <code>maxdevtools</code>:"},{"type":"list","items":["<strong>Placement:</strong> Inserted on the master track alongside candidate devices.","<strong>Mechanism:</strong> Queries Live's audio engine thread timers and measures instantaneous and average processing cycles per audio buffer vector.","<strong>Reporting:</strong> Displays precise CPU utilization metrics in percentage and milliseconds, allowing developers to isolate heavy DSP subpatchers without relying on generic system task managers."],"ordered":false},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-----------------------------------------------------------------------+\n|  cpu-reporter.amxd (Master Track Device)                              |\n+-----------------------------------------------------------------------+\n|  Target Device:  [ Analog_Drive_Filter                              ] |\n|  Audio Vector:   128 Samples @ 48.0 kHz                               |\n|  Process Time:   0.142 ms  ( 5.3 % Audio Thread Budget )              |\n|  Peak Spike:     0.280 ms  ( 10.5 % Audio Thread Budget )             |\n+-----------------------------------------------------------------------+</pre>"}]},{"type":"step","title":"5. Source Citations","blocks":[{"type":"list","items":["Ableton AG. (2023). <em>Ableton maxdevtools Repository &amp; Architecture Specifications</em>. Berlin: Ableton AG (<code>maxdevtools-main</code>).","Ableton AG. (2023). <em>maxdiff: Visual Git Diff Utility for Max and Max for Live</em>. Ableton Developer Documentation.","Ableton AG. (2023). <em>cpu-reporter: Real-Time Audio Thread Profiler</em>. Ableton Developer Documentation."],"ordered":false}]}],"minutes":8}],"exercises":[]}]};
